import sys

def count_numbers_with_power_of_2(n, e):
    power_of_2 = str(2 ** e)
    length = len(power_of_2)

    # dp[i][j] will store the number of valid numbers with i digits ending with j
    dp = [[0] * 10 for _ in range(length + 1)]
    dp[0][0] = 1

    for i in range(1, length + 1):
        for j in range(10):
            for k in range(10):
                if str(k) == power_of_2[i - 1]:
                    dp[i][j] += dp[i - 1][k]
                else:
                    dp[i][j] += dp[i - 1][k]

    count = 0
    for i in range(1, length + 1):
        for j in range(10):
            count += dp[i][j]

    # Check numbers with fewer digits than length
    for i in range(1, length):
        count += 10 ** i

    # Check if the number n itself contains the power of 2
    if power_of_2 <= str(n):
        count += 1

    return count

